import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachFreeControl, createFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };
export interface Walkthrough { readonly camera: FreeCamera; jumpTo(eye: Vec, target: Vec): void; dispose(): void; }

function copyVec(v: { x: number; y: number; z: number }, p: Vec): void {
  v.x = p.x; v.y = p.y; v.z = p.z;
}

function orientationFrom(eye: Vec, target: Vec): { yaw: number; pitch: number } {
  const dx = target.x - eye.x;
  const dy = target.y - eye.y;
  const dz = target.z - eye.z;
  const len = Math.hypot(dx, dy, dz);
  if (len === 0) return { yaw: 0, pitch: 0 };
  const ny = dy / len;
  return { yaw: Math.atan2(dx, dz), pitch: Math.asin(Math.min(1, Math.max(-1, ny))) };
}

export function createWalkthrough(canvas: HTMLCanvasElement, scene: SceneContext, eye: Vec, target: Vec): Walkthrough {
  const camera = createFreeCamera(eye, target);
  scene.camera = camera;
  let detach = attachFreeControl(camera, canvas, scene);
  let disposed = false;

  return {
    camera,
    jumpTo(eye: Vec, target: Vec): void {
      copyVec(camera.position, eye);
      copyVec(camera.target, target);

      // Keep the free-camera's internal yaw/pitch in step with the new look direction.
      const probe = createFreeCamera(eye, target);
      const fallback = orientationFrom(eye, target);
      const useProbe = probe._yaw !== 0 || probe._pitch !== 0 || (Math.abs(fallback.yaw) < 1e-6 && Math.abs(fallback.pitch) < 1e-6);
      camera._yaw = useProbe ? probe._yaw : fallback.yaw;
      camera._pitch = useProbe ? probe._pitch : fallback.pitch;
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      detach();
    }
  };
}
```
