import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachFreeControl, createFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };
export interface Walkthrough { readonly camera: FreeCamera; jumpTo(eye: Vec, target: Vec): void; dispose(): void; }

function setVec(v: { x: number; y: number; z: number }, p: Vec): void {
  v.x = p.x;
  v.y = p.y;
  v.z = p.z;
}

function fallbackYawPitch(eye: Vec, target: Vec): { yaw: number; pitch: number } {
  const dx = target.x - eye.x;
  const dy = target.y - eye.y;
  const dz = target.z - eye.z;
  const len = Math.hypot(dx, dy, dz);
  if (len < 1e-8) return { yaw: 0, pitch: 0 };
  const ny = dy / len;
  return { yaw: Math.atan2(dx, dz), pitch: Math.asin(Math.min(1, Math.max(-1, ny))) };
}

export function createWalkthrough(canvas: HTMLCanvasElement, scene: SceneContext, eye: Vec, target: Vec): Walkthrough {
  const camera = createFreeCamera(eye, target);
  scene.camera = camera;
  const detach = attachFreeControl(camera, canvas, scene);
  let disposed = false;

  return {
    camera,
    jumpTo(eye: Vec, target: Vec): void {
      setVec(camera.position, eye);
      setVec(camera.target, target);

      const reference = createFreeCamera(eye, target);
      const fallback = fallbackYawPitch(eye, target);
      const useReference =
        reference._yaw !== 0 ||
        reference._pitch !== 0 ||
        (Math.abs(fallback.yaw) < 1e-6 && Math.abs(fallback.pitch) < 1e-6);

      camera._yaw = useReference ? reference._yaw : fallback.yaw;
      camera._pitch = useReference ? reference._pitch : fallback.pitch;
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      detach();
    }
  };
}
```
